// <snippet:settings>
// Settings come from n8n Variables; self-hosted community installs without
// Variables fall back to environment variables of the same name.
function setting(name) {
  try {
    return $vars?.[name] || $env[name];
  } catch {
    // Env access is blocked and there is no Variable: treat as unset.
  }
}
function required(name) {
  const value = setting(name);
  if (!value) {
    throw new Error(
      `${name} is not set (n8n Variable or environment variable)`
    );
  }
  return value;
}
// </snippet:settings>

// Signs the request for overdue loans. Secret: n8n Variable LENDLOOP_INBOUND_SECRET
// (same value as Convex env N8N_INBOUND_SECRET).
const crypto = require('crypto');
const secret = required('LENDLOOP_INBOUND_SECRET');

const path = '/n8n/overdue-loans';
const url = required('LENDLOOP_CONVEX_SITE_URL').replace(/\/+$/, '') + path;
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = 'v1=' + crypto
  .createHmac('sha256', secret)
  .update(`${timestamp}.GET.${path}.`)
  .digest('hex');
return [{ json: { url, timestamp, signature } }];

