// Convex signs its response too: only email loans this data really came from.
const crypto = require('crypto');
const MAX_SKEW_SECONDS = 300;
const secret = required('LENDLOOP_INBOUND_SECRET');
const res = $input.first().json;
const headers = res.headers || {};
const raw = typeof res.body === 'string' ? res.body : null;
const timestamp = headers['x-lendloop-timestamp'];
const signature = headers['x-lendloop-signature'] || '';

if (raw === null) throw new Error('Expected a text response body (Response Format: Text)');
if (!timestamp || !signature.startsWith('v1=')) throw new Error('Convex response is not signed');
const seconds = Number(timestamp);
if (!Number.isInteger(seconds) || Math.abs(Date.now() / 1000 - seconds) > MAX_SKEW_SECONDS) {
  throw new Error('Convex response signature is stale');
}
const expected = crypto
  .createHmac('sha256', secret)
  .update(`${timestamp}.RESPONSE./n8n/overdue-loans.${raw}`)
  .digest();
const given = Buffer.from(signature.slice(3), 'hex');
if (given.length !== expected.length || !crypto.timingSafeEqual(given, expected)) {
  throw new Error('Convex response signature does not match');
}

// One item per overdue loan; no loans means the run simply ends here.
const { appUrl, loans, reminderDate } = JSON.parse(raw);
return loans.map((loan) => ({ json: { ...loan, appUrl, reminderDate } }));

