// Signs the reminder outcome; Convex stores it once per loan per day.
const crypto = require('crypto');
const secret = required('LENDLOOP_INBOUND_SECRET');

const body = JSON.stringify($json);
const url = required('LENDLOOP_CONVEX_SITE_URL').replace(/\/+$/, '') + '/n8n/reminders';
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = 'v1=' + crypto
  .createHmac('sha256', secret)
  .update(`${timestamp}.POST./n8n/reminders.${body}`)
  .digest('hex');
return { json: { url, body, timestamp, signature } };
